class Solution:
    def twoSum(self, nums, target):
        # pos 保存已经扫描过的数字及其下标，用哈希表快速查找另一半。
        pos = {}
        for i, num in enumerate(nums):
            # 当前数是 num，要凑成 target，另一半必须是 target - num。
            need = target - num
            # 先查找再记录当前数，保证不会把同一个下标使用两次。
            if need in pos:
                return [pos[need], i]
            # 记录当前数，供后面的数查找；重复值也能找到两个不同下标。
            pos[num] = i

