class Solution:
    def maxArea(self, height):
        # 两端指针表示当前容器边界；宽度是 right-left，高度由较短板决定。
        left, right = 0, len(height) - 1
        # ans 记录搜索过程中最大的面积。
        ans = 0
        while left < right:
            ans = max(ans, (right - left) * min(height[left], height[right]))
            # 移动长板只会减小宽度且不能提高短板；只有移动短板才可能得到更大面积。
            if height[left] < height[right]:
                left += 1
            else:
                right -= 1
        return ans

