class Solution:
    def threeSum(self, nums):
        # 先排序，才能根据总和大小移动双指针，并让相同数字相邻以便去重。
        nums.sort()
        res = []
        n = len(nums)
        # 固定第一个数，另外两个数在它右边用双指针寻找。
        for i in range(n - 2):
            # 相同的第一个数只处理一次，避免生成重复三元组。
            if i > 0 and nums[i] == nums[i - 1]:
                continue
            # left、right 对应第二和第三个数，三个下标始终不同。
            left, right = i + 1, n - 1
            while left < right:
                s = nums[i] + nums[left] + nums[right]
                if s == 0:
                    res.append([nums[i], nums[left], nums[right]])
                    left += 1
                    right -= 1
                    # 找到答案后，跳过已经使用过的相同值。
                    while left < right and nums[left] == nums[left - 1]:
                        left += 1
                    while left < right and nums[right] == nums[right + 1]:
                        right -= 1
                # 排序后，左指针右移会增大总和，右指针左移会减小总和。
                elif s < 0:
                    left += 1
                else:
                    right -= 1
        return res

