class Solution:
    def letterCombinations(self, digits):
        if not digits:
            return []

        mapping = {
            "2": "abc", "3": "def", "4": "ghi", "5": "jkl",
            "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"
        }

        res = []
        path = []

        def dfs(index):
            # index 表示现在要处理 digits 的第几位
            if index == len(digits):
                res.append("".join(path))
                return

            letters = mapping[digits[index]]

            for ch in letters:
                path.append(ch)        # 选择当前字母
                dfs(index + 1)         # 处理下一位数字
                path.pop()             # 撤销选择

        dfs(0)
        return res

