class Solution:
    def isValid(self, s):
        # mp 的作用是：
        # 遇到右括号时，可以立刻知道它应该匹配哪个左括号
        mp = {
            ')': '(',
            ']': '[',
            '}': '{'
        }

        # stack 里专门存“还没被匹配掉的左括号”
        stack = []

        for ch in s:
            # 如果是左括号，就先放进栈里
            if ch in '([{':
                stack.append(ch)
            else:
                # 如果是右括号，先看栈有没有东西
                # 没有的话，说明它找不到左括号来配
                if not stack:
                    return False

                # 再看栈顶是不是它应该匹配的左括号
                if stack[-1] != mp[ch]:
                    return False

                # 配对成功，就把这个左括号弹出
                stack.pop()

        # 最后必须栈为空，才说明没有多余的左括号残留
        return len(stack) == 0

