import heapq

class Solution:
    def mergeKLists(self, lists):
        heap = []

        # 先把每条链表当前的头节点放进最小堆
        for i, node in enumerate(lists):
            if node:
                heapq.heappush(heap, (node.val, i, node))

        dummy = ListNode()
        cur = dummy

        while heap:
            # 取出当前最小的节点
            _, i, node = heapq.heappop(heap)

            # 接到答案链表后面
            cur.next = node
            cur = cur.next

            # 如果它后面还有节点，就把“这条链表新的头”再放进堆里
            if node.next:
                heapq.heappush(heap, (node.next.val, i, node.next))
        return dummy.next

class Solution:
    def longestValidParentheses(self, s):
        n = len(s)

        # dp[i] 表示：以下标 i 结尾的最长有效括号长度
        dp = [0] * n
        ans = 0

        for i in range(1, n):
            if s[i] == ")":
                # 情况 1: 直接形成 "()"
                if s[i - 1] == "(":
                    dp[i] = 2

                    # 如果前面还有一段有效括号，可以接上
                    if i >= 2:
                        dp[i] += dp[i - 2]
                else:
                    # 情况 2: 前一个也是 ")"
                    # 先拿到以前一个位置结尾的有效长度
                    prev_len = dp[i - 1]

                    # 再去找：和当前这个 ")" 配对的 "(" 应该在哪
                    match_index = i - prev_len - 1

                    if match_index >= 0 and s[match_index] == "(":
                        # 先把前一段有效括号 + 新配成的一对括号算进去
                        dp[i] = dp[i - 1] + 2

                        # 如果这对括号左边还有别的有效括号，也可以再接上
                        if match_index - 1 >= 0:
                            dp[i] += dp[match_index - 1]

                # 每次更新后，顺手维护全局最大值
                ans = max(ans, dp[i])

        return ans

