class Solution:
    def firstMissingPositive(self, nums):
        # 长度为 n 的数组，缺失的最小正数一定在 1 到 n+1 之间。
        n = len(nums)
        for i in range(n):
            # 把数字 x 放到下标 x-1；只处理有效范围，目标位已相同则停止，避免重复值死循环。
            while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
                # 先保存目标下标，再交换，避免交换过程中 nums[i] 的值改变。
                j = nums[i] - 1
                nums[i], nums[j] = nums[j], nums[i]
        # 第一次循环把数字归位，第二次找第一个不符合“值=下标+1”的位置。
        for i in range(n):
            if nums[i] != i + 1:
                return i + 1
        # 1 到 n 都齐全时，缺失的最小正数就是 n+1。
        return n + 1

