class Solution:
    def minDistance(self, word1, word2):
        m = len(word1)
        n = len(word2)

        # dp[i][j] 表示：
        # 把 word1 前 i 个字符 变成 word2 前 j 个字符，最少要几步
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # word1 前 i 个字符变成空串，只能一直删
        for i in range(m + 1):
            dp[i][0] = i

        # 空串变成 word2 前 j 个字符，只能一直插
        for j in range(n + 1):
            dp[0][j] = j

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if word1[i - 1] == word2[j - 1]:
                    # 最后一个字符相同，这一位不用新操作
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    # 三种操作里选代价最小的：
                    # 1. 删除
                    # 2. 插入
                    # 3. 替换
                    dp[i][j] = min(
                        dp[i - 1][j] + 1,      # 删除
                        dp[i][j - 1] + 1,      # 插入
                        dp[i - 1][j - 1] + 1   # 替换
                    )

        return dp[m][n]

