from collections import Counter

class Solution:
    def minWindow(self, s, t):
        need = Counter(t)
        missing = len(t)
        left = 0
        start = 0
        min_len = float('inf')
        for right, ch in enumerate(s):
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1
            while missing == 0:
                if right - left + 1 < min_len:
                    min_len = right - left + 1
                    start = left
                need[s[left]] += 1
                if need[s[left]] > 0:
                    missing += 1
                left += 1
        return "" if min_len == float('inf') else s[start:start + min_len]

class Solution:
    def exist(self, board, word):
        rows = len(board)
        cols = len(board[0])

        def dfs(r, c, index):
            # index 表示当前要匹配 word[index]
            if index == len(word):
                return True

            # 越界，直接失败
            if r < 0 or r >= rows or c < 0 or c >= cols:
                return False

            # 字符不匹配，直接失败
            if board[r][c] != word[index]:
                return False

            # 先保存原字符，再做访问标记
            temp = board[r][c]
            board[r][c] = "#"

            found = (
                dfs(r + 1, c, index + 1) or
                dfs(r - 1, c, index + 1) or
                dfs(r, c + 1, index + 1) or
                dfs(r, c - 1, index + 1)
            )

            # 回溯：恢复现场
            board[r][c] = temp
            return found

        for r in range(rows):
            for c in range(cols):
                if dfs(r, c, 0):
                    return True

        return False

