class Solution:
    def isValidBST(self, root):
        # prev 记录中序遍历时，上一个访问到的值
        prev = None

        def dfs(node):
            nonlocal prev
            if not node:
                return True

            # 先检查左子树
            if not dfs(node.left):
                return False

            # 中序遍历访问当前节点时，
            # 当前值必须比上一个值更大
            if prev is not None and node.val <= prev:
                return False

            # 更新上一个值
            prev = node.val

            # 再检查右子树
            return dfs(node.right)

        return dfs(root)

