class Solution:
    def maxDepth(self, root):
        # TreeNode 由力扣提供；空树没有任何层，深度为 0。
        if not root:
            return 0
        # 栈里保存 (节点, 所在层数)，根节点属于第 1 层。
        # 用循环代替递归，单边很深的树也不会触发 RecursionError。
        stack = [(root, 1)]
        ans = 0
        while stack:
            node, depth = stack.pop()
            ans = max(ans, depth)
            # 孩子的层数比父节点多 1，只把非空孩子压入栈。
            if node.left:
                stack.append((node.left, depth + 1))
            if node.right:
                stack.append((node.right, depth + 1))
        return ans

