class Solution:
    def maxPathSum(self, root):
        # TreeNode 由力扣提供；显式后序遍历先计算孩子，再计算父节点。
        if not root:
            return 0
        stack = [(root, False)]
        gain = {}
        # 不能初始化为 0，否则全负数的树会错误地选择“空路径”。
        ans = float('-inf')
        while stack:
            node, ready = stack.pop()
            if not ready:
                # False 表示首次到达；True 表示左右孩子已处理完。
                stack.append((node, True))
                if node.right:
                    stack.append((node.right, False))
                if node.left:
                    stack.append((node.left, False))
            else:
                # 负贡献可以不选；父节点用完孩子的临时值后将其删除。
                left = max(gain.pop(node.left, 0), 0)
                right = max(gain.pop(node.right, 0), 0)
                # 路径以当前节点为最高点时，可以同时使用左右两条链。
                ans = max(ans, node.val + left + right)
                # 交给父节点时只能延伸一条链，否则会形成分叉而不是路径。
                gain[node] = node.val + max(left, right)
        return ans

