    def partition(self, s):
        res = []
        path = []

        def is_palindrome(sub):
            # 判断一个字符串是否是回文串
            return sub == sub[::-1]

        def dfs(start):
            # start 走到末尾，说明已经完成一种切分
            if start == len(s):
                res.append(path[:])
                return

            # 枚举下一刀切在哪里
            for end in range(start, len(s)):
                sub = s[start:end + 1]

                if not is_palindrome(sub):
                    continue

                path.append(sub)
                dfs(end + 1)
                path.pop()

        dfs(0)
        return res

