    def detectCycle(self, head):
        # 第 1 阶段：先判断有没有环
        slow = fast = head
        while True:
            # fast 走不到两步，说明没有环
            if not fast or not fast.next:
                return None
            slow = slow.next
            fast = fast.next.next
            if slow == fast:
                break

        # 第 2 阶段：一个从头出发，一个从相遇点出发
        # 两个都一次走一步，再次相遇就是入环点
        slow = head
        while slow != fast:
            slow = slow.next
            fast = fast.next
        return slow

