class Solution:
    def getIntersectionNode(self, headA, headB):
        # 比较的是节点对象身份，值相同不代表两条链表相交。
        a, b = headA, headB
        # 两指针分别走完 A+B 和 B+A，总路程相同，会在交点或共同的 None 相遇。
        while a != b:
            # 走到尾部后切到另一条链表，从而消除两条链表的长度差。
            a = a.next if a else headB
            b = b.next if b else headA
        return a

