class Solution:
    def majorityElement(self, nums):
        # candidate 表示当前候选人
        candidate = None

        # count 表示当前候选人的净票数
        count = 0

        for num in nums:
            # 如果票数清零，就换一个新的候选人
            if count == 0:
                candidate = num

            # 遇到和候选人相同的，就加票
            # 不同的，就减票
            if num == candidate:
                count += 1
            else:
                count -= 1

        return candidate

