class Solution:
    def rightSideView(self, root):
        # TreeNode 由力扣提供；空树没有右视图。
        if not root:
            return []
        q = deque([root])
        res = []
        while q:
            # 固定本层节点数，新加入的孩子留到下一轮。
            size = len(q)
            for i in range(size):
                node = q.popleft()
                # 先左后右入队，因此这一层最后取出的节点就是最右节点。
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
                if i == size - 1:
                    res.append(node.val)
        return res

