class Solution:
    def numIslands(self, grid):
        if not grid or not grid[0]:
            return 0
        rows, cols = len(grid), len(grid[0])
        ans = 0
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] != '1':
                    continue
                # 每遇到一个未访问的陆地，就发现了一座新岛。
                ans += 1
                stack = [(i, j)]
                # 入栈时立即标记，避免同一格被多个邻居重复加入。
                # 这份解法会把输入 grid 中访问过的 '1' 改成 '0'。
                grid[i][j] = '0'
                while stack:
                    r, c = stack.pop()
                    # 只连上下左右，斜对角不属于同一座岛。
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                            grid[nr][nc] = '0'
                            stack.append((nr, nc))
                # 显式栈代替递归，大面积连通陆地也不会超出递归深度。
        return ans

