class Solution:
    def findKthLargest(self, nums, k):
        # 本题数值范围是 [-10000, 10000]，可以用有界计数达到线性时间。
        # low 用来把负数平移为非负下标；范围 R 最大只有 20001。
        low, high = min(nums), max(nums)
        count = [0] * (high - low + 1)
        for num in nums:
            count[num - low] += 1
        # 从大到小数元素，重复值也各占一个名次，而不是只数不同数字。
        for index in range(len(count) - 1, -1, -1):
            k -= count[index]
            if k <= 0:
                return index + low
        # 题目保证 1<=k<=len(nums)，因此一定会在循环内找到答案。

