class Solution:
    def lowestCommonAncestor(self, root, p, q):
        # TreeNode 由力扣提供；题目保证 p、q 都在树中且互不相同。
        # parent 记录每个节点的父节点；比较的是节点身份，不是仅比较 val。
        parent = {root: None}
        stack = [root]
        while p not in parent or q not in parent:
            node = stack.pop()
            if node.left:
                parent[node.left] = node
                stack.append(node.left)
            if node.right:
                parent[node.right] = node
                stack.append(node.right)
        # 先收集 p 和它的全部祖先，再从 q 向上寻找第一个交点。
        ancestors = set()
        while p:
            ancestors.add(p)
            p = parent[p]
        while q not in ancestors:
            q = parent[q]
        # 不使用递归，特别深的树也能处理；父节点表占 O(n) 空间。
        return q

