from collections import deque

class Solution:
    def maxSlidingWindow(self, nums, k):
        # 队列存下标，对应的值从队头到队尾递减，队头始终是当前最大值。
        q = deque()
        res = []
        for i, num in enumerate(nums):
            # 下标小于窗口左端的候选已经过期，必须先移除。
            while q and q[0] <= i - k:
                q.popleft()
            # 新值更大且更晚过期，队尾较小的值再也不可能成为最大值，可以淘汰。
            while q and nums[q[-1]] <= num:
                q.pop()
            q.append(i)
            # 收集满 k 个数后，才开始输出窗口答案。
            if i >= k - 1:
                res.append(nums[q[0]])
        return res

