from collections import Counter

class Solution:
    def topKFrequent(self, nums, k):
        # count[num] 是出现频次；题面要求时间优于 O(n log n)。
        count = Counter(nums)
        # 频次最多是 len(nums)，buckets[f] 保存所有出现 f 次的数字。
        buckets = [[] for _ in range(len(nums) + 1)]
        for num, frequency in count.items():
            buckets[frequency].append(num)
        # 从高频桶向低频桶取数，收集到 k 个就结束，不需要比较排序。
        answer = []
        for frequency in range(len(nums), 0, -1):
            for num in buckets[frequency]:
                answer.append(num)
                if len(answer) == k:
                    return answer
        # 题目保证 k 合法且答案唯一，返回顺序可以任意。

class Solution:
    def pathSum(self, root, targetSum):
        if not root:
            return 0
        # count 只保存当前根到节点路径上的前缀和，空前缀 0 先出现一次。
        count = {0: 1}
        ans = 0
        # (节点, 前缀和, 是否离开节点)：离开时撤销计数，模拟递归回溯。
        stack = [(root, 0, False)]
        while stack:
            node, prefix, leaving = stack.pop()
            if leaving:
                count[prefix] -= 1
                if count[prefix] == 0:
                    del count[prefix]
                continue
            current = prefix + node.val
            # 当前和减去某个祖先前缀等于 targetSum，就找到一条向下路径。
            # 必须先查再加，避免 targetSum=0 时把空路径也计入。
            ans += count.get(current - targetSum, 0)
            count[current] = count.get(current, 0) + 1
            # 离开事件先入栈、最后执行，保证计数只对当前分支有效。
            stack.append((node, current, True))
            if node.right:
                stack.append((node.right, current, False))
            if node.left:
                stack.append((node.left, current, False))
        return ans

