class Solution:
    def partitionLabels(self, s):
        # 记录每个字符最后出现的位置
        last = {}
        for i, ch in enumerate(s):
            last[ch] = i

        res = []
        start = 0
        end = 0

        for i, ch in enumerate(s):
            # 当前片段的最远右边界
            end = max(end, last[ch])

            # 走到边界，说明可以切分
            if i == end:
                res.append(end - start + 1)
                start = i + 1

        return res

