class Solution:
    def longestCommonSubsequence(self, text1, text2):
        m = len(text1)
        n = len(text2)

        # dp[i][j] 表示：
        # text1 前 i 个字符 和 text2 前 j 个字符 的最长公共子序列长度
        # 多开一行一列，是为了更方便处理空串边界
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                # 注意这里是 i-1 和 j-1
                # 因为 dp 用的是“前 i 个字符”的定义，比真实下标大 1
                if text1[i - 1] == text2[j - 1]:
                    # 最后一个字符相同，可以一起接上
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    # 最后一个字符不同，只能舍弃其中一个，选更优结果
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[m][n]

